-- Model: lnk_billablecharge_timesheet__billablecharge_hkey_curr
-- Description: Current active relationship for LNK_BILLABLECHARGE_TIMESHEET using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_BILLABLECHARGE_TIMESHEET_HKEY AS LNK_BILLABLECHARGE_TIMESHEET_HKEY,
    l.BILLABLECHARGE_HKEY AS BILLABLECHARGE_HKEY,
    l.TIMESHEET_HKEY AS TIMESHEET_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls.DATELASTSYNC

    ROW_NUMBER() OVER (
        PARTITION BY l.BILLABLECHARGE_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls.DATELASTSYNC
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_billablecharge_timesheet') }} l
INNER JOIN {{ ref('lks_bh1_billablecharge_timesheet_curr') }} ls
    ON l.LNK_BILLABLECHARGE_TIMESHEET_HKEY = ls.LNK_BILLABLECHARGE_TIMESHEET_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
